"use strict";(self.webpackChunk=self.webpackChunk||[]).push([["1375"],{7695:function(s,a,n){n.r(a),n.d(a,{default:function(){return p}});var t=n(1147);let l=["innerHTML"],p={setup:()=>({html:""}),render:()=>((0,t.wg)(),(0,t.iD)("div",{class:"mi-doc-markdown-body",innerHTML:'<h1>上传提交页</h1>\n<div class="mi-doc-card"><h3 id="jie-shao" tabindex="-1">介绍</h3>\n<p>上传提交页适合实名认证、工单反馈、资料补充、售后凭证上传等移动业务页面。</p>\n<p>该场景使用 <code>NoticeBar</code>、<code>CellGroup</code>、<code>Uploader</code>、<code>Tag</code>、<code>Button</code> 和 <code>Empty</code> 组合出一个完整资料提交页面，包含规则提示、资料状态、上传入口、补充说明和提交后的结果反馈。</p>\n</div><div class="mi-doc-card"><h3 id="tui-jian-zu-jian" tabindex="-1">推荐组件</h3>\n<table>\n<thead>\n<tr>\n<th>组件</th>\n<th>作用</th>\n</tr>\n</thead>\n<tbody>\n<tr>\n<td>NoticeBar</td>\n<td>展示上传规则</td>\n</tr>\n<tr>\n<td>CellGroup</td>\n<td>聚合资料区块</td>\n</tr>\n<tr>\n<td>Uploader</td>\n<td>上传图片或文件</td>\n</tr>\n<tr>\n<td>Tag</td>\n<td>标记审核状态</td>\n</tr>\n<tr>\n<td>Button</td>\n<td>提交资料</td>\n</tr>\n<tr>\n<td>Empty</td>\n<td>展示提交后的结果说明</td>\n</tr>\n</tbody>\n</table>\n</div><div class="mi-doc-card"><h3 id="shi-li-dai-ma" tabindex="-1">示例代码</h3>\n<pre><code class="language-html"><span class="hljs-tag">&lt;<span class="hljs-name">mi-nav-bar</span> <span class="hljs-attr">title</span>=<span class="hljs-string">&quot;资料上传&quot;</span> <span class="hljs-attr">left-arrow</span> <span class="hljs-attr">left-text</span>=<span class="hljs-string">&quot;返回&quot;</span> /&gt;</span>\n\n<span class="hljs-tag">&lt;<span class="hljs-name">mi-notice-bar</span>\n    <span class="hljs-attr">left-icon</span>=<span class="hljs-string">&quot;info-o&quot;</span>\n    <span class="hljs-attr">text</span>=<span class="hljs-string">&quot;请上传清晰、完整的证件照片，单次最多 3 张&quot;</span>\n/&gt;</span>\n\n<span class="hljs-tag">&lt;<span class="hljs-name">mi-cell-group</span> <span class="hljs-attr">inset</span> <span class="hljs-attr">title</span>=<span class="hljs-string">&quot;审核资料&quot;</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">mi-cell</span> <span class="hljs-attr">title</span>=<span class="hljs-string">&quot;资料状态&quot;</span>&gt;</span>\n        <span class="hljs-tag">&lt;<span class="hljs-name">template</span> #<span class="hljs-attr">value</span>&gt;</span>\n            <span class="hljs-tag">&lt;<span class="hljs-name">mi-tag</span> <span class="hljs-attr">type</span>=<span class="hljs-string">&quot;warning&quot;</span>&gt;</span>待补充<span class="hljs-tag">&lt;/<span class="hljs-name">mi-tag</span>&gt;</span>\n        <span class="hljs-tag">&lt;/<span class="hljs-name">template</span>&gt;</span>\n    <span class="hljs-tag">&lt;/<span class="hljs-name">mi-cell</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">mi-cell</span> <span class="hljs-attr">title</span>=<span class="hljs-string">&quot;上传凭证&quot;</span> <span class="hljs-attr">label</span>=<span class="hljs-string">&quot;支持身份证、营业执照、现场照片&quot;</span>&gt;</span>\n        <span class="hljs-tag">&lt;<span class="hljs-name">template</span> #<span class="hljs-attr">value</span>&gt;</span>\n            <span class="hljs-tag">&lt;<span class="hljs-name">span</span>&gt;</span>2/3<span class="hljs-tag">&lt;/<span class="hljs-name">span</span>&gt;</span>\n        <span class="hljs-tag">&lt;/<span class="hljs-name">template</span>&gt;</span>\n    <span class="hljs-tag">&lt;/<span class="hljs-name">mi-cell</span>&gt;</span>\n    <span class="hljs-tag">&lt;<span class="hljs-name">mi-uploader</span> <span class="hljs-attr">v-model</span>=<span class="hljs-string">&quot;fileList&quot;</span> <span class="hljs-attr">multiple</span> <span class="hljs-attr">:max-count</span>=<span class="hljs-string">&quot;3&quot;</span> /&gt;</span>\n<span class="hljs-tag">&lt;/<span class="hljs-name">mi-cell-group</span>&gt;</span>\n\n<span class="hljs-tag">&lt;<span class="hljs-name">mi-button</span> <span class="hljs-attr">round</span> <span class="hljs-attr">block</span> <span class="hljs-attr">type</span>=<span class="hljs-string">&quot;primary&quot;</span> @<span class="hljs-attr">click</span>=<span class="hljs-string">&quot;onSubmit&quot;</span>&gt;</span> 提交审核 <span class="hljs-tag">&lt;/<span class="hljs-name">mi-button</span>&gt;</span>\n\n<span class="hljs-tag">&lt;<span class="hljs-name">mi-empty</span> <span class="hljs-attr">description</span>=<span class="hljs-string">&quot;提交后会通过短信通知审核结果&quot;</span> /&gt;</span>\n</code></pre>\n</div><div class="mi-doc-card"><h3 id="gua-yong-chang-jing" tabindex="-1">适用场景</h3>\n<ul>\n<li>实名认证、资质认证、发票资料补充</li>\n<li>工单反馈、售后凭证、巡检照片上传</li>\n<li>需要统一上传规则、资料状态和提交动作的页面</li>\n</ul>\n</div><div class="mi-doc-card"><h3 id="shi-yong-jian-yi" tabindex="-1">使用建议</h3>\n<ul>\n<li>上传前先用 <code>NoticeBar</code> 说明格式、大小和清晰度要求。</li>\n<li>用 <code>Tag</code> 标记资料状态，让用户知道当前是否还需补充。</li>\n<li>提交后展示明确的结果说明和下一步动作。</li>\n</ul>\n</div>'},null,8,l))}}}]);